-- Creates the merchants table and the append-only audit_events table.
--
-- Timestamps have no database default: the application supplies them from its
-- injected clock. Identifiers are UUIDs generated by the application.

CREATE TABLE merchants (
  id uuid NOT NULL,
  legal_name varchar(200) NOT NULL,
  display_name varchar(100) NOT NULL,
  business_type varchar(50) NOT NULL,
  industry varchar(100) NOT NULL,
  country_code varchar(2) NOT NULL,
  default_currency varchar(3) NOT NULL,
  status varchar(20) NOT NULL,
  created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL,
  CONSTRAINT merchants_pkey PRIMARY KEY (id),
  -- The status values mirror MERCHANT_STATUSES in packages/domain.
  CONSTRAINT merchants_status_check CHECK (status IN ('DRAFT', 'ACTIVE', 'SUSPENDED')),
  -- The varchar types bound the length in characters. The checks require at least
  -- one non-whitespace character.
  CONSTRAINT merchants_legal_name_check CHECK (legal_name ~ '\S'),
  CONSTRAINT merchants_display_name_check CHECK (display_name ~ '\S'),
  CONSTRAINT merchants_business_type_check CHECK (business_type ~ '\S'),
  CONSTRAINT merchants_industry_check CHECK (industry ~ '\S'),
  -- Only the format of the codes is checked: two uppercase letters for ISO 3166-1
  -- alpha-2 and three for ISO 4217. Membership in the ISO lists is not enforced.
  CONSTRAINT merchants_country_code_check CHECK (country_code ~ '^[A-Z]{2}$'),
  CONSTRAINT merchants_default_currency_check CHECK (default_currency ~ '^[A-Z]{3}$'),
  CONSTRAINT merchants_updated_at_check CHECK (updated_at >= created_at)
);

COMMENT ON TABLE merchants IS 'Merchant accounts. Every merchant-owned table in later migrations references merchants (id).';
COMMENT ON COLUMN merchants.default_currency IS 'ISO 4217 code, checked for format only. USD as the single supported currency is enforced by the application (Money), so a new currency needs no schema change.';

CREATE TABLE audit_events (
  id uuid NOT NULL,
  occurred_at timestamptz NOT NULL,
  actor_type varchar(20) NOT NULL,
  actor_id varchar(128) NOT NULL,
  action varchar(64) NOT NULL,
  target_type varchar(64) NOT NULL,
  target_id varchar(128) NOT NULL,
  merchant_id uuid,
  correlation_id varchar(64) NOT NULL,
  metadata jsonb NOT NULL,
  CONSTRAINT audit_events_pkey PRIMARY KEY (id),
  CONSTRAINT audit_events_merchant_id_fkey FOREIGN KEY (merchant_id) REFERENCES merchants (id),
  CONSTRAINT audit_events_actor_type_check CHECK (actor_type IN ('API_KEY', 'SYSTEM')),
  CONSTRAINT audit_events_actor_id_check CHECK (actor_id ~ '\S'),
  CONSTRAINT audit_events_action_check CHECK (action ~ '^[A-Z][A-Z0-9_]{0,63}$'),
  CONSTRAINT audit_events_target_type_check CHECK (target_type ~ '^[A-Z][A-Z0-9_]{0,63}$'),
  CONSTRAINT audit_events_target_id_check CHECK (target_id ~ '\S'),
  -- Same pattern the API accepts for X-Correlation-Id (AD-30).
  CONSTRAINT audit_events_correlation_id_check CHECK (correlation_id ~ '^[A-Za-z0-9._-]{8,64}$'),
  CONSTRAINT audit_events_metadata_check CHECK (jsonb_typeof(metadata) = 'object' AND octet_length(metadata::text) <= 8192)
);

COMMENT ON TABLE audit_events IS 'Append-only audit trail. A trigger rejects UPDATE, DELETE, and TRUNCATE. A superuser or the table owner can still disable the trigger, so this is not tamper-proof.';
COMMENT ON COLUMN audit_events.actor_id IS 'API key identifier for API_KEY actors, or a fixed component name for SYSTEM actors.';
COMMENT ON COLUMN audit_events.merchant_id IS 'The merchant the event concerns, when there is one.';
COMMENT ON COLUMN audit_events.metadata IS 'Structured, non-sensitive context as a JSON object of at most 8192 bytes. It must never contain secrets, API keys, payment tokens, or payment credentials.';

CREATE FUNCTION audit_events_reject_change() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'audit_events is append-only: % is not allowed', TG_OP
    USING ERRCODE = 'restrict_violation';
END;
$$;

-- A statement-level trigger also rejects statements that match no row.
CREATE TRIGGER audit_events_append_only
BEFORE UPDATE OR DELETE OR TRUNCATE ON audit_events
FOR EACH STATEMENT
EXECUTE FUNCTION audit_events_reject_change();
